7	[ApiController]
8	[Route("api/products")]
9	public class ProductsController(CatalogService catalogService) : ControllerBase
10	{
11	    [HttpGet]
12	    public async Task<ActionResult<ProductListResponse>> GetProducts([FromQuery] int page = 1, [FromQuery] string? categoryId = null, [FromQuery] string? subcategoryId = null, [FromQuery] string? sortBy = null, [FromQuery] string? sortDirection = null, [FromQuery] string? search = null, [FromQuery] Dictionary<string, string>? properties = null, CancellationToken ct = default)
13	    {
14	        var result = await catalogService.GetProductsAsync(page, categoryId, subcategoryId, sortBy, sortDirection, search, properties, ct);
15	
16	        var response = new ProductListResponse
17	        {
18	            Items = result.Items.Select(p => new ProductSummaryDto { Id = p.Id, Name = p.Name }).ToList(),
19	            Page = result.Page,
20	            PageSize = result.PageSize,
21	            TotalCount = result.TotalCount
22	        };
23	
24	        return Ok(response);
25	    }
26	
27	    [HttpGet("{id}")]
28	    public async Task<ActionResult<ProductDetailDto>> GetProduct(string id, CancellationToken ct = default)
29	    {
30	        var detail = await catalogService.GetProductDetailAsync(id, ct);
31	        if (detail is null)
32	        {
33	            return NotFound();
34	        }
35	
36	        var product = detail.Product;
37	        var response = new ProductDetailDto
38	        {
39	            Id = product.Id,
40	            Name = product.Name,
41	            Description = product.Description,
42	            Category = new CategoryRefDto { Id = product.Subcategory!.Category!.Id, Name = product.Subcategory.Category.Name },
43	            Subcategory = new SubcategoryRefDto { Id = product.Subcategory.Id, Name = product.Subcategory.Name },
44	            Properties = product.PropertyValues
45	                .OrderBy(pv => pv.Name, StringComparer.Ordinal)
46	                .Select(pv => new ProductPropertyDto { Name = pv.Name, Value = pv.Value })
47	                .ToList(),
48	            AverageRating = detail.AverageRating,
49	            RatingCount = detail.RatingCount,
50	            Offers = product.Offers
51	                .OrderBy(o => o.Price)
52	                .ThenBy(o => o.SupplierId, StringComparer.Ordinal)
53	                .Select(o => new SupplierOfferDto { SupplierId = o.SupplierId, SupplierName = o.Supplier!.Name, Price = o.Price })
54	                .ToList()
55	        };
56	
57	        return Ok(response);
58	    }
59	}
