5	namespace seed_b_backend.Api.Application;
6	
7	public class CatalogService(AppDbContext context)
8	{
9	    public const int PageSize = 20;
10	
11	    public async Task<PagedResult<Product>> GetProductsAsync(
12	        int page,
13	        string? categoryId = null,
14	        string? subcategoryId = null,
15	        string? sortBy = null,
16	        string? sortDirection = null,
17	        string? search = null,
18	        IReadOnlyDictionary<string, string>? propertyFilters = null,
19	        CancellationToken ct = default)
20	    {
21	        var query = context.Products.AsQueryable();
22	        if (!string.IsNullOrWhiteSpace(subcategoryId))
23	        {
24	            query = query.Where(p => p.SubcategoryId == subcategoryId);
25	        }
26	        else if (!string.IsNullOrWhiteSpace(categoryId))
27	        {
28	            query = query.Where(p => p.Subcategory!.CategoryId == categoryId);
29	        }
30	
31	        if (!string.IsNullOrWhiteSpace(search))
32	        {
33	            var normalizedSearch = search.Trim().ToLowerInvariant();
34	            query = query.Where(p =>
35	                p.Name.ToLower().Contains(normalizedSearch) ||
36	                p.Description.ToLower().Contains(normalizedSearch));
37	        }
38	
39	        if (propertyFilters is not null)
40	        {
41	            foreach (var (propertyName, propertyValue) in propertyFilters)
42	            {
43	                var name = propertyName;
44	                var value = propertyValue;
45	                query = query.Where(p => p.PropertyValues.Any(pv => pv.Name == name && pv.Value == value));
46	            }
47	        }
48	
49	        var totalCount = await query.CountAsync(ct);
50	
51	        var descending = string.Equals(sortDirection, "desc", StringComparison.OrdinalIgnoreCase);
52	        query = sortBy?.ToLowerInvariant() switch
53	        {
54	            "price" => descending
55	                ? query.OrderBy(p => p.Offers.Any() ? 0 : 1)
56	                       .ThenByDescending(p => p.Offers.Min(o => (decimal?)o.Price))
57	                       .ThenBy(p => p.Id)
58	                : query.OrderBy(p => p.Offers.Any() ? 0 : 1)
59	                       .ThenBy(p => p.Offers.Min(o => (decimal?)o.Price))
60	                       .ThenBy(p => p.Id),
61	            "name" => descending
62	                ? query.OrderByDescending(p => p.Name).ThenBy(p => p.Id)
63	                : query.OrderBy(p => p.Name).ThenBy(p => p.Id),
64	            "viewcount" => descending
65	                ? query.OrderByDescending(p => p.ViewCount).ThenBy(p => p.Id)
66	                : query.OrderBy(p => p.ViewCount).ThenBy(p => p.Id),
67	            _ => query.OrderBy(p => p.Id)
68	        };
69	
70	        var skip = (long)(page - 1) * PageSize;
71	
72	        var items = page < 1 || skip > int.MaxValue
73	            ? new List<Product>()
74	            : await query.Skip((int)skip).Take(PageSize).ToListAsync(ct);
75	
76	        return new PagedResult<Product>
77	        {
78	            Items = items,
79	            Page = page,
80	            PageSize = PageSize,
81	            TotalCount = totalCount
82	        };
83	    }
